### [x] Task 9 — Write backend tests for `GET /api/data/tasks`

Create `autom9-backend/tests/api/test_data.py`:

```python
import pytest
from httpx import AsyncClient

pytestmark = pytest.mark.asyncio(loop_scope="session")

SESSION_HEADERS = {"X-Autom9-Session": "test-session-id"}


# ---------------------------------------------------------------------------
# GET /api/data/tasks — no config loaded
# ---------------------------------------------------------------------------


async def test_get_tasks_no_config_returns_404(client: AsyncClient):
    """When no workflow config is loaded, endpoint returns 404."""
    response = await client.get("/api/data/tasks", headers=SESSION_HEADERS)
    assert response.status_code == 404


# ---------------------------------------------------------------------------
# GET /api/data/tasks — config without data_panel
# ---------------------------------------------------------------------------


async def test_get_tasks_no_data_panel_returns_404(client: AsyncClient, monkeypatch):
    import app.api.data as data_module
    from app.config.workflow_registry import WorkflowRegistry

    registry = WorkflowRegistry()
    registry._active = {
        "version": "1.0.0",
        "workflow_id": "test",
        "tools": [],
        "agent_instructions": "test",
        # no data_panel key
    }
    monkeypatch.setattr(data_module, "workflow_registry", registry)

    response = await client.get("/api/data/tasks", headers=SESSION_HEADERS)
    assert response.status_code == 404


# ---------------------------------------------------------------------------
# GET /api/data/tasks — config with data_panel but no google_docs_url
# ---------------------------------------------------------------------------


async def test_get_tasks_no_google_docs_url_returns_404(client: AsyncClient, monkeypatch):
    import app.api.data as data_module
    from app.config.workflow_registry import WorkflowRegistry

    registry = WorkflowRegistry()
    registry._active = {
        "version": "1.0.0",
        "workflow_id": "test",
        "tools": [],
        "agent_instructions": "test",
        "data_panel": {"worksheet_name": "Sheet1"},  # no google_docs_url
    }
    monkeypatch.setattr(data_module, "workflow_registry", registry)

    response = await client.get("/api/data/tasks", headers=SESSION_HEADERS)
    assert response.status_code == 404


# ---------------------------------------------------------------------------
# GET /api/data/tasks — integration stub raises IntegrationError → 503
# ---------------------------------------------------------------------------


async def test_get_tasks_integration_unavailable_returns_503(client: AsyncClient, monkeypatch):
    import app.api.data as data_module
    from app.config.workflow_registry import WorkflowRegistry
    from app.core.exceptions import IntegrationError

    registry = WorkflowRegistry()
    registry._active = {
        "version": "1.0.0",
        "workflow_id": "test",
        "tools": [],
        "agent_instructions": "test",
        "data_panel": {"worksheet_name": "Sheet1", "google_docs_url": "https://docs.example.com/d/abc"},
    }
    monkeypatch.setattr(data_module, "workflow_registry", registry)

    # Stub integration that raises
    class _FailingDocs:
        async def execute(self, action: str, params: dict) -> dict:
            raise IntegrationError("google_docs", "Google Docs not configured")

    monkeypatch.setattr(data_module, "_google_docs", _FailingDocs())

    response = await client.get("/api/data/tasks", headers=SESSION_HEADERS)
    assert response.status_code == 503


# ---------------------------------------------------------------------------
# GET /api/data/tasks — happy path
# ---------------------------------------------------------------------------


async def test_get_tasks_returns_task_list(client: AsyncClient, monkeypatch):
    import app.api.data as data_module
    from app.config.workflow_registry import WorkflowRegistry

    registry = WorkflowRegistry()
    registry._active = {
        "version": "1.0.0",
        "workflow_id": "test",
        "tools": [],
        "agent_instructions": "test",
        "data_panel": {"worksheet_name": "Sheet1", "google_docs_url": "https://docs.example.com/d/abc"},
    }
    monkeypatch.setattr(data_module, "workflow_registry", registry)

    class _StubDocs:
        async def execute(self, action: str, params: dict) -> dict:
            return {"tasks": ["Review scope", "Update sheet"]}

    monkeypatch.setattr(data_module, "_google_docs", _StubDocs())

    response = await client.get("/api/data/tasks", headers=SESSION_HEADERS)
    assert response.status_code == 200
    body = response.json()
    assert "data" in body
    assert "meta" in body
    assert len(body["data"]) == 2
    assert body["data"][0]["text"] == "Review scope"


async def test_get_tasks_response_has_request_id(client: AsyncClient, monkeypatch):
    import app.api.data as data_module
    from app.config.workflow_registry import WorkflowRegistry

    registry = WorkflowRegistry()
    registry._active = {
        "version": "1.0.0",
        "workflow_id": "test",
        "tools": [],
        "agent_instructions": "test",
        "data_panel": {"worksheet_name": "Sheet1", "google_docs_url": "https://docs.example.com/d/abc"},
    }
    monkeypatch.setattr(data_module, "workflow_registry", registry)

    class _StubDocs:
        async def execute(self, action: str, params: dict) -> dict:
            return {"tasks": []}

    monkeypatch.setattr(data_module, "_google_docs", _StubDocs())

    response = await client.get("/api/data/tasks", headers=SESSION_HEADERS)
    assert response.status_code == 200
    assert "request_id" in response.json()["meta"]
```

**Testing approach:** Use `monkeypatch` to set `workflow_registry._active` and `_google_docs` directly on the module — no DB required for these tests. This follows the pattern used in `test_integrations.py` for provider factory testing.

---

## Dev Notes

### No migration required

`DataPanel.svelte` and `GET /api/data/tasks` use no new DB tables. The Tableau worksheet is read client-side via the Extensions API; Google Docs is an external call via the existing `GoogleDocsIntegration` stub. No new Alembic version needed.

### Workflow config backwards compatibility

`data_panel` is optional in `WorkflowConfigSchema`. Existing configs that lack this field will still validate (`model_validate` ignores unknown fields by default in Pydantic v2 — note: this also means extra fields pass silently). Configs already stored in DB are re-parsed by `get_tool_definitions()` and `validate_schema()` — adding an optional field does not break those calls.

### Tableau worksheet API — dev/test fallback

`getWorksheetData()` returns `[]` immediately when no Tableau runtime is present. This means `DataPanel.svelte` in dev will show "No data available" in the worksheet section — expected. Tests do not need to mock the Tableau runtime.

### Google Docs stub — current behaviour

`GoogleDocsIntegration.execute()` always raises `IntegrationError("google_docs", "Google Docs not configured")`. The `GET /api/data/tasks` endpoint catches this and returns 503. The DataPanel frontend catches 503 (as `ApiError`) and shows the error in the tasks section while the worksheet section remains unaffected.

### `Promise.allSettled` is mandatory

Must use `Promise.allSettled` (not `Promise.all`) for the two independent data fetches in `onMount`. `Promise.all` rejects on first failure — this would break the NFR9 isolation guarantee.

### `_google_docs` as module-level singleton

Follows the pattern of `_INTEGRATION_MAP` in `app/api/integrations.py`. Module-level singleton is acceptable in v1 (single-process async). Avoid instantiating `GoogleDocsIntegration()` inside the request handler.

### Generic rendering — no field name coupling

The worksheet table renders `Object.keys(row[0])` as column headers. If the Tableau data source adds or renames a field, the panel still renders correctly. No conditional logic like `if col === "open_days"` anywhere in `DataPanel.svelte`.

