    current_type = "internal"
    opportunities: list[dict] = []

    for line in _extract_lines(document):
        if _BILLABLE_HEADER_RE.match(line):
            current_type = "billable"
        elif _INTERNAL_HEADER_RE.match(line):
            current_type = "internal"
        else:
            opportunities.append(
                {"title": line, "type": current_type, "details": line}
            )

    return opportunities


