_INTERNAL_HEADER_RE = re.compile(r"^(internal|internal\s+work)\s*$", re.IGNORECASE)
_HEADING_STYLES = (
    "TITLE",
    "SUBTITLE",
    "HEADING_1",
    "HEADING_2",
    "HEADING_3",
    "HEADING_4",
    "HEADING_5",
    "HEADING_6",
)

